window.LESSONS=[
{id:8,title:'讀懂條文，不只看字面',topic:'總則入門',minutes:8,concept:'法律解釋',intro:'讀法條，要同時理解文字、制度脈絡與規範目的；解釋仍然要有最起碼的文字依據。',points:['先讀清楚條文對象、條件和法律效果。','把相鄰條文、整體制度與制定背景一併考慮。','解釋不能完全脫離文字；覺得公平並不足以改寫規定。'],example:'有人單憑條文中的一個詞，認為自己必然有權。你先找出完整句子及相關條文，檢查他的理解是否符合制度脈絡。',counter:'只說「這樣比較合理」，卻完全找不到文字對應，並不是充分的法律解釋。',advanced:'第八條要求兼顧字面與體系。進階閱讀時，分辨文義、體系、歷史及目的方面的論證，再檢查每一步是否仍有文字基礎。法律解釋與第九條的漏洞填補也不能混為一談。',prompt:'如果日常語言與條文在制度中的用語不同，你會如何安排解釋步驟？',rubric:['交代字面可能含義','查閱同制度相關條文','分析背景與目的','說明最起碼文字對應的界線'],related:[9,10],questions:[{q:'理解一條法律，最合適的方法是？',options:['只用日常字典意思','結合文字、整體法制及適用情況','完全按自己的公平感'],answer:1,why:'第八條要求超越單純字面，同時保留最起碼的文字對應。'},{q:'某解釋完全沒有條文文字依據，但你覺得結果公平，可以直接當作立法思想嗎？',options:['不可以，仍需最起碼文字對應','可以，公平感優先於一切','只要多人同意就可以'],answer:0,why:'第八條第二款明確設定文字對應的界線。'}]},
{id:1299,title:'共有一個物，不等於各佔一個角落',topic:'生活與樓宇',minutes:7,concept:'共有與份額',intro:'兩人或以上同時對同一物擁有所有權，可以形成共有；份額描述權利比例，不當然對應物理劃分。',points:['先確認是否對同一物共同擁有所有權。','共有人的份額可以不同，但權利的質量相同。','設定依據没有相反指定時，推定份額相同。'],example:'甲乙共同擁有一個車庫，設定依據載明各佔一半。這不當然代表甲擁有左半、乙擁有右半；如何使用仍要另行處理。',counter:'同住一個住所，不代表住戶都擁有該住所的所有權。',advanced:'區分共有份額、使用安排及分割。第1299條提供概念，第1301條涉及共有人地位，第1302條處理使用。分層所有權及其共同部分還需核對特別制度，不能將普通共有規則直接當成全部大廈管理規則。',prompt:'兩人各有一半份額，其中一人主張自己專有房屋的其中一間房，還要查甚麼？',rubric:['區分抽象份額與物理分割','查閱設定依據','查使用協議或規章','識別是否涉及特別制度'],related:[1301,1302,1303],questions:[{q:'共有房屋各佔一半，是否必然等於各自專有指定房間？',options:['必然如此','不必然，份額與使用安排不同','先入住者擁有所有房間'],answer:1,why:'第1299條的份額是共有權比例；具體使用需結合其他規定或安排。'},{q:'設定依據未指定份額，原則上如何理解？',options:['推定各人份額相同','推定年長者佔較多','一律由先使用者決定'],answer:0,why:'第1299條第二款訂明，在設定依據無相反指定時推定份額相同。'}]},
{id:1302,title:'共同擁有，怎樣共同使用？',topic:'生活與樓宇',minutes:7,concept:'共有物使用',intro:'沒有訂立使用規章時，共有人可以使用共有物，但要尊重用途及其他共有人的同等使用權。',points:['先查有沒有使用規章。','使用不能偏離原定用途。','使用不能剝奪其他共有人的同等使用權。'],example:'甲乙共有一個作儲物用途的倉庫，沒有使用規章。甲把全部門鎖換掉並拒絕乙進入，便涉及剝奪乙使用權的問題。',counter:'自己曾長期使用整個共有物，不當然變成單獨占有；第1302條第二款另有占有名義轉變的例外。',advanced:'使用、占有與所有权並非同義。分析時須分清事實上使用、占有名義，以及權利歸屬；不要單憑使用時間長短推定產權。遇到分層建築物共同部分，亦須查相應特別法。',prompt:'某共有人獨自用了倉庫多年，如何分析其他人能否要求使用？',rubric:['核對共有權及規章','確認原定用途','檢查其他人是否被排除','區分使用與占有名義'],related:[1299,1301,1303],questions:[{q:'無使用規章時，共有人可以把共有倉庫鎖上，永久拒絕其他共有人使用嗎？',options:['只要自己有份額便可以','不可以藉此剝奪其他人的同等使用權','先換鎖的人有優先權'],answer:1,why:'第1302條第一款要求不剝奪其他共同權利人的同等使用權。'},{q:'其中一人使用共有物，是否必然構成其單獨占有？',options:['是','否，須注意占有名義轉變的例外','只看他有沒有交水電費'],answer:1,why:'第1302條第二款區分使用與單獨占有，並保留占有名義轉變的例外。'}]},
{id:477,title:'有損失，就一定有人要賠？',topic:'生活與樓宇',minutes:9,concept:'侵權損害賠償',intro:'一般過錯侵權責任，不能只看「有損失」；還要分析行為、不法性、過錯及損害與行為的關聯。',points:['辨認被侵犯的權利或保護利益的規定。','分辨故意、過失與需要另外適用的無過錯責任。','整理損害及因果關係的證據，不以猜測代替。'],example:'樓下天花出現水漬。先記錄損害，再調查漏水來源、涉及的管道及相關行為；不能僅因樓上位置較高就直接認定全部責任。',counter:'有損害並不自動證明某一人的過錯；無過錯賠償亦要有法律規定。',advanced:'第477條是一般起點；第480條涉及過錯證明，第557條涉及因果關係。具體事件可能涉及合同責任、法定推定或特別責任，不能用同一證明模型機械套用。',prompt:'住戶報稱樓上漏水造成家具損毀，你會把哪些問題列為待證事實？',rubric:['損害及金額','漏水來源與相關行為','不法性與過錯或適用推定','行為與損害之因果關係'],related:[479,480,557],questions:[{q:'樓下有水漬，能否只憑位置直接認定樓上住戶負全部賠償責任？',options:['可以，位置已足夠','不可以，還須查來源及責任要件','只有管理員能決定'],answer:1,why:'一般侵權責任須核對法定要件，不能把位置推測直接當成責任證明。'},{q:'不取決於有無過錯的損害賠償義務，何時存在？',options:['任何人覺得公平時','僅在法律規定的情況','只要損失很大'],answer:1,why:'第477條第二款明確要求法律規定。'}]},
{id:399,title:'合同自由，也有界線',topic:'合同與生意',minutes:8,concept:'合同自由',intro:'當事人可以設計合同內容，但自由在法律限制範圍內行使。',points:['可以在法定範圍內自由設定內容。','可以訂立法典未列明的合同。','雙方接受的條款仍需符合相應法律限制。'],example:'兩人合作提供攝影與剪片服務，可以按需要約定交付內容、費用及修改次數；不能只因双方簽字就認為任何條款均有效。',counter:'「雙方同意，所以法律一律不能干預」忽略了第399條的限制。',advanced:'先判斷交易性質，再看強制規定、形式要求及特別法。與第400條對照：內容設定自由與合同成立後的拘束力是不同問題。',prompt:'朋友拿來一份自擬合作合同，你會按甚麼次序檢查？',rubric:['辨認交易及當事人','核對強制規定及形式','釐清權利義務','區分成立、有效與履行'],related:[400],questions:[{q:'法典沒有列明的合同類型，是否一概不能訂立？',options:['一概不能','可以，但在法律限制範圍內','只有口頭才可以'],answer:1,why:'第399條允許訂立不同於法典規定的合同，但保留法律限制。'},{q:'雙方簽字是否代表全部條款必然有效？',options:['是，簽名排除法律限制','否，仍須核對法律限制','只要有見證人就全部有效'],answer:1,why:'合同自由並非無限制；簽名不能自動排除法定限制。'}]},
{id:251,title:'代人簽約，效力歸誰？',topic:'合同與生意',minutes:8,concept:'代理',intro:'代理人在被賦予的權限內，以被代理人名義作出的法律行為，效力在被代理人的權利義務範圍內產生。',points:['確認以誰的名義作出行為。','核對代理權的來源和範圍。','區分有權代理與無權代理，不能只看口頭自稱。'],example:'甲授權乙以甲名義購買指定設備。乙在權限內訂約，相關效力歸於甲；若乙超出權限，便要另查無權代理等規定。',counter:'某人聲稱「我是代表」，不等於已證明有權代理。',advanced:'第253條容許第三人要求代理人證明權力。分析無權代理時要另讀相應規定，不能直接沿用第251條的通常效果；代理與單純傳達訊息亦要區分。',prompt:'有人代表業主簽約，簽約前你會核對甚麼？',rubric:['被代理人身分','以誰名義簽約','代理權來源與範圍','權力證明與交易形式'],related:[253,255,261],questions:[{q:'代理人在權限內以被代理人名義作出的法律行為，通常對誰產生效力？',options:['被代理人','必然只對代理人','任何見證人'],answer:0,why:'第251條規定其效力在被代理人的權利義務範圍內產生。'},{q:'对方自稱獲授權，你是否可以要求其證明代理權？',options:['不可以','可以，參照第253條','只有公證員可以問'],answer:1,why:'第253條容許第三人要求代理人在合理期間內證明權力。'}]}
];

window.LESSONS.unshift(...[{"id": 1, "title": "法律規則，從哪裏來？", "topic": "總則入門", "minutes": 7, "concept": "直接淵源", "intro": "先辨認規則的來源，才判斷它有何法律地位。第1條以法律為直接淵源，並界定本條所指的法律。", "points": ["辨認制定機關及其立法權限。", "區分法律、私人約定及日常做法。", "適用於澳門的國際協約與普通法律的關係，亦須留意。"], "example": "商戶說「同行一向這樣收費」，你先要求找出相關法律、約定或其他依據，不能單憑一句慣例就當作法律。", "counter": "私人訂下的規則不會單憑名稱叫「規定」就變成立法機關制定的法律。", "advanced": "原文第二款涉及機關及權限，第三款涉及適用於澳門的國際協約。不要把所有官方資訊都等同法律規範；也不要將此條當成全部規範位階問題的答案。", "prompt": "一張告示自稱有法律效力，你會先核對甚麼？", "rubric": ["制定者", "制定權限", "文件性質與適用範圍", "正式原文及依據"], "related": [2, 3], "questions": [{"q": "同行長年使用的收費辦法，是否單憑此點就成為第1條的法律？", "options": ["是，夠多人用就算", "否，要辨认其法律來源", "只要印成告示就算"], "answer": 1, "why": "第1條涉及法律的直接淵源及制定權限，不能把一般做法直接等同法律。"}, {"q": "本條指出，適用於澳門的國際協約與普通法律有甚麼關係？", "options": ["國際協約優於普通法律", "普通法律一律優先", "只看哪份文件較短"], "answer": 0, "why": "第1條第三款明確規定適用於澳門的國際協約優於普通法律。"}]}, {"id": 2, "title": "「一直都係咁」有法律效力嗎？", "topic": "總則入門", "minutes": 7, "concept": "習慣之法律價值", "intro": "第2條不是讓所有慣常做法自動成為法律，而是設定考慮習慣的條件。", "points": ["須不違背善意原則。", "須法律有所規定，才予考慮。", "先證明做法內容，再核對法律是否容許援用。"], "example": "交易一方以「行業習慣」要求額外收費。分析時先查有沒有容許考慮該習慣的法律依據，並檢查是否違背善意。", "counter": "廣泛流行不等於必然符合法律容許及善意兩項要求。", "advanced": "不要混淆習慣、合同中的明示條款，以及當事人過往履行方式。它們可能在不同制度下有不同意義，不能僅靠第2條一概處理。", "prompt": "有人引用行業慣例，你會要求甚麼資料？", "rubric": ["慣例的具體內容", "其存在的證據", "容許考慮的法律規定", "是否違背善意"], "related": [1, 399], "questions": [{"q": "第2條要求在甚麼情況下考慮習慣？", "options": ["只要歷史悠久", "不違背善意，且法律有所規定", "只要一方堅持"], "answer": 1, "why": "不違背善意與法律有所規定，均是條文要求。"}, {"q": "「大家一直這樣做」足以完成法律分析嗎？", "options": ["足夠", "不足夠，仍要核對法定條件", "只看多數人意見"], "answer": 1, "why": "慣常做法本身不足以取代對第2條條件的檢查。"}]}, {"id": 3, "title": "法院可以只按「公平」裁判嗎？", "topic": "總則入門", "minutes": 7, "concept": "衡平原則", "intro": "法院按衡平原則處理案件有法定入口，並非任何情況都可以只依公平感決定。", "points": ["法律規定容許時可以。", "當事人合意，且法律關係不是不可處分者，亦是條文所列情況。", "預先約定須符合條文對仲裁條款規定的要求。"], "example": "雙方要求法院「不用看規則，覺得公平就好」。仍須核對第3條列出的情況，不能只憑這句要求就跳過法律條件。", "counter": "衡平並非讓法官任意決定；当事人合意也不是唯一需要檢查的事項。", "advanced": "分清依法律作出裁判、法律使用衡平標準，以及当事人按法定條件選擇衡平處理。尤其注意不可處分法律關係的限制。", "prompt": "雙方同意按衡平處理，你仍須核對甚麼？", "rubric": ["是否有法律容許", "合意的內容", "法律關係是否可處分", "預先約定是否符合相關規定"], "related": [8], "questions": [{"q": "法院是否可以在任何案件中只按個人公平感裁判？", "options": ["可以", "不可以，須符合第3條所列情況", "只要案件金額低就可以"], "answer": 1, "why": "第3條以列舉情況限制按衡平原則處理案件。"}, {"q": "以當事人合意作為依據時，還要留意甚麼？", "options": ["法律關係並非不可處分者", "當事人必須是親戚", "必須沒有書面資料"], "answer": 0, "why": "第3條b項同時要求合意及法律關係非為不可處分者。"}]}, {"id": 4, "title": "公布了，就立即生效嗎？", "topic": "總則入門", "minutes": 7, "concept": "法律開始生效", "intro": "公布與生效是兩個步驟。法律要在公報公布，並要核對法定生效時間。", "points": ["須在澳門特別行政區公報公布後才具約束力。", "先看法律本身是否定出公布至生效的期間。", "沒有定出時，本條規定自公布後第六日開始生效。"], "example": "你看到新法新聞，先找公報原文及生效條款，不能把新聞日期直接當作適用日期。", "counter": "「已通過」「已公布」「已生效」不應混用。", "advanced": "有些法律對不同條款安排不同生效時間，或設過渡規則。實際適用尚須查第11條及特別規定；計算具體日期亦要核對相應期間規則。", "prompt": "新法公布後，一宗舊合同爭議是否立即適用新法？", "rubric": ["公報公布日期", "生效條款", "過渡規定", "法律在時間上的適用"], "related": [11, 12], "questions": [{"q": "要確認新法何時生效，應先看甚麼？", "options": ["新聞刊登日期", "法律本身的生效規定", "社交平台轉發時間"], "answer": 1, "why": "第4條先以法律本身定出的公布至生效期間為準。"}, {"q": "法律本身沒有定出生效期間，本條的補充規則是？", "options": ["公布後第六日", "公布前一日", "永遠不生效"], "answer": 0, "why": "第4條第二款規定自公布後第六日開始生效。"}]}, {"id": 5, "title": "不知道法律，可以免責嗎？", "topic": "總則入門", "minutes": 7, "concept": "不知法律與錯誤解釋", "intro": "第5條指出，不知道法律或解釋錯誤，本身不構成不遵守法律的合理理由。", "points": ["分清不了解法律與不了解事實。", "不能只靠「我不知道」主張毋須遵守。", "具體責任仍須另行核對相關制度與法定要件。"], "example": "有人收到爭議通知，說「我從未聽過這條法例」。這句話本身不能代替核對義務與責任的分析。", "counter": "本條並不表示任何人只要解釋錯誤就自動負全部責任；仍須查適用的責任規則。", "advanced": "區分一般遵守法律義務與特定制度中的錯誤問題。不要把第5條直接當成全部刑事、行政或民事責任的結論。", "prompt": "當事人說自己理解錯誤，你會如何繼續分析？", "rubric": ["指出本條的一般規則", "釐清是法律或事實上的認識問題", "確認具體適用制度", "核對各項責任要件"], "related": [8], "questions": [{"q": "「我不知道這條法律」本身是否足以成為不遵守的合理理由？", "options": ["是", "否", "只要沒有讀過就可以"], "answer": 1, "why": "第5條明確否定此理由本身的免責效果。"}, {"q": "第5條是否取代一切具體責任要件的審查？", "options": ["不會，仍須分析相關制度", "會，毋須再看其他條文", "只取決於當事人年齡"], "answer": 0, "why": "本條的一般規則不能代替具體責任制度及其要件分析。"}]}, {"id": 6, "title": "新法出現，舊法一定失效？", "topic": "總則入門", "minutes": 7, "concept": "法律終止生效", "intro": "要識別廢止的方式、範圍與一般法和特別法的關係，不能只比較日期。", "points": ["可以明確廢止，也可能因新舊規定抵觸或全面重新規範而廢止。", "一般法原則上不廢止特別法，除非立法者另有明確意思。", "廢止一部廢止法律，不會自動使更早的法律復活。"], "example": "新的一般規定公布後，有人說某項舊的特別規定必然失效。應查立法者意思及具體規範關係，不能只看新舊先後。", "counter": "「廢止廢止法」不等於被廢止的舊法自動再次生效。", "advanced": "先區分暫時生效法律及非暫時生效法律，再分析明示廢止、規定抵觸及整體替代。法律失效與既有事實的效果亦要分開判斷。", "prompt": "找到新舊兩項規定時，你怎樣核對仍適用哪一項？", "rubric": ["廢止條款", "內容是否抵觸", "是否全面規範同一事宜", "一般法與特別法及過渡規定"], "related": [11, 12], "questions": [{"q": "新的「一般法」是否必然廢止舊的「特別法」？", "options": ["必然", "不必然，須留意立法者另有明確意思的情況", "只看哪一份較長"], "answer": 1, "why": "第6條第三款訂明一般法不廢止特別法，但立法者另有明確意思者除外。"}, {"q": "廢止一部廢止法律，較早被廢止的法律會自動恢復嗎？", "options": ["會", "不會", "只要有人要求就會"], "answer": 1, "why": "第6條第四款否定自動恢復效力。"}]}]);

window.LESSONS.push(...[{"id": 7, "title": "條文不清楚，法院可以不判嗎？", "topic": "總則入門", "minutes": 8, "concept": "審判義務", "intro": "法律沒有規定或文字有疑問，不是法院拒絕審判的藉口。", "points": ["法院和法官獨立，僅受法律拘束。", "不得以法律空白、含糊或事實疑問為藉口拒絕審判。", "裁判須考慮應作類似處理的案件，以促進解釋與適用統一。"], "example": "雙方為新型交易爭議起訴，法律沒有直接使用該交易名稱。法院仍须依法處理，可能涉及解釋或漏洞填補。", "counter": "必須審判不等於必須支持原告，也不代表法院可以忽略證據及程序。", "advanced": "分辨裁判義務、事實證明不足的後果與法律漏洞。第7條第3款要求考慮類似案件；不能因此推論所有既往判決都具有完全相同的拘束力。", "prompt": "面對無直接條文的新交易，法院還有哪些分析工具？", "rubric": ["釐清事實與請求", "解釋現有規定", "判斷是否有漏洞", "考慮應類似處理的案件"], "related": [8, 9], "questions": [{"q": "找不到直接規定，法院能否只以此為由拒絕審判？", "options": ["不能", "可以", "只要雙方不懂法律便可以"], "answer": 0, "why": "第7條第2款不容許以法律無規定等理由拒絕審判。"}, {"q": "法院必須處理爭議，是否表示原告必然勝訴？", "options": ["是", "否，仍要依法審查事實與請求", "只看起訴先後"], "answer": 1, "why": "審判義務與個案勝負是不同問題。"}]}, {"id": 9, "title": "沒有直接規定，下一步怎樣找？", "topic": "總則入門", "minutes": 8, "concept": "法律漏洞填補", "intro": "確認法律沒有規範相關情況後，先考慮是否有理由相通的類似情況可供處理。", "points": ["不是外觀相似便足夠，規範理由也要相通。", "先找適用於類似情況的規定。", "沒有類似情況時，仍須根據法制精神處理。"], "example": "兩種新舊交易表面不同，但你懷疑其風險與規範理由相同；先辨認規則背後理由，再評估是否適合類推。", "counter": "自己不熟悉某條法例，不等於法律真的有漏洞。", "advanced": "與第8條解釋區分：先確定現有規定能否涵蓋，再談填補。第10條另禁止例外規定作類推適用，所以找到相似規則後仍須檢查其性質。", "prompt": "看到類似情況時，應如何證明可以援用其規則？", "rubric": ["確認無直接規範", "列出規範理由", "比較理由是否同樣成立", "檢查例外規定等限制"], "related": [8, 10], "questions": [{"q": "法律上的類似，是否只要事物外觀接近？", "options": ["是", "否，規範理由也須在未規範情況中成立", "只看名稱"], "answer": 1, "why": "第9條第2款以法律規範所依據的理由是否同樣成立判斷類似。"}, {"q": "沒有找到直接條文，是否可以立刻自行定一條規則？", "options": ["不可以，先查有無適用於類似情況的規定", "可以，完全自由", "只要當事人贊同就可以"], "answer": 0, "why": "第9條先考慮類似情況，無類似情況才按第3款處理。"}]}, {"id": 10, "title": "類推與擴張解釋，有何不同？", "topic": "總則入門", "minutes": 8, "concept": "例外規定", "intro": "第10條對例外規定劃出界線：不容許類推適用，但容許擴張解釋。", "points": ["先判斷規定是否屬例外規定。", "解釋是在釐清規定本來的涵蓋範圍。", "類推是在法律未規範的情況借用另一規則。"], "example": "某項例外只為特定情形而設。分析另一情形時，須說明它本就在規定的合理含義內，還是因理由相似才想借用該例外。", "counter": "把推理叫做「解釋」，不會自動令原本禁止的類推變得可行。", "advanced": "此條要與第8條文字對應及第9條漏洞填補並讀。真實爭議往往在於如何辨認例外及涵蓋範圍，而不是只背兩個名詞。", "prompt": "你如何分辨是在解釋既有規定，還是在填補漏洞？", "rubric": ["識別規定性質", "分析文字與制度範圍", "指出情況是否已被涵蓋", "說明有無借用規則處理空白"], "related": [8, 9], "questions": [{"q": "例外規定能否作類推適用？", "options": ["不能", "能，一律可以", "只要結果方便即可"], "answer": 0, "why": "第10條明確禁止例外規定作類推適用。"}, {"q": "例外規定是否也禁止擴張解釋？", "options": ["是", "否，條文容許擴張解釋", "完全毋須解釋"], "answer": 1, "why": "第10條同時容許擴張解釋，應與類推區分。"}]}, {"id": 11, "title": "新法律，會影響舊關係嗎？", "topic": "總則入門", "minutes": 8, "concept": "法律在時間上的適用", "intro": "不能單憑事件發生在新法前，就斷定所有部分永遠只適用舊法。先看新法規範的是哪一種問題。", "points": ["法律原則上規範將來情況。", "對事實有效條件或效果的規定，與直接規範持續法律關係內容的規定要區分。", "另查追溯效力、過渡條款及既有法律效果。"], "example": "一項持續多年的法律關係遇上新法。先區分爭議是成立時的有效條件，還是新法生效後關係內容的規範，再查過渡規定。", "counter": "「合同舊，所以新法永遠無關」及「新法生效，舊效果全部推翻」都過於簡化。", "advanced": "第11條第2款包含兩種不同處理方向。將時間軸分成成立事實、已產生效果、新法生效與其後關係，有助避免混淆；仍應以個別法律的過渡制度為先。", "prompt": "分析新舊法時，時間軸應列哪些節點？", "rubric": ["引致法律關係的事實", "既有法律效果", "新法生效時點", "其後仍持續的法律關係"], "related": [4, 6, 12], "questions": [{"q": "持續存在的法律關係，是否必然完全不受新法規範？", "options": ["是", "否，要看新法是否直接規範關係內容及過渡規定", "只看當事人意願"], "answer": 1, "why": "第11條第2款對直接規範法律關係內容的情況設有不同方向。"}, {"q": "新法有追溯效力時，已產生的效果如何理解？", "options": ["仍推定保留，須核對具體規定", "必定一律消失", "必定全部重新計算"], "answer": 0, "why": "第11條第1款對已產生的效果設有保留推定。"}]}, {"id": 12, "title": "解釋性法律，也能推翻已確定結果？", "topic": "總則入門", "minutes": 8, "concept": "解釋性法律", "intro": "解釋性法律成為被解釋法律的構成部分，但條文同時保留若干已產生的效果。", "points": ["留意債的履行、確定判決及和解等效果的保留。", "和解是否已認可，並非第1款所列保留的唯一分界。", "對尚未獲法院認可的訴訟捨棄或認諾，第2款另有規定。"], "example": "新法律解釋某項舊規定，當事人便想推翻先前的確定判決。分析時須查第12條對既有結果的保留。", "counter": "解釋性法律不等於所有已結束的事情都要重新處理。", "advanced": "區分解釋性法律與真正改變制度的新法。第2款的特殊處理還要求新法對捨棄人或認諾人有利，而且尚未經法院認可，不能省略任何條件。", "prompt": "面對新解釋性法律，應先查既往事件已走到哪一步？", "rubric": ["是否已履行", "是否已有確定判決", "有無和解等相類行為", "捨棄或認諾是否已獲認可及新法是否有利"], "related": [11], "questions": [{"q": "解釋性法律是否必然推翻確定判決已產生的效果？", "options": ["不是，第12條保留該等效果", "是，一律推翻", "只看當事人要求"], "answer": 0, "why": "第12條第1款列明因確定判決等已產生的效果予以保留。"}, {"q": "第12條第2款涉及的捨棄或認諾，要留意哪組條件？", "options": ["尚未經法院認可，且解釋性法律對該人有利", "只要想反悔便可以", "只看案件金額"], "answer": 0, "why": "第2款把未經認可及對當事人有利列為相關條件。"}]}]);
window.LESSONS.push(...[{"id": 13, "title": "不是本地居民，也有民事權利嗎？", "topic": "總則入門", "minutes": 9, "concept": "非本地居民的民事權利", "intro": "第13條以民事權利平等為原則，同時保留法律另有規定的例外。", "points": ["先分清民事權利與其他類別的權利。", "非本地居民原則上享有同等民事權利。", "如主張有例外，要找出相關法律依據。"], "example": "非本地居民在澳門購買家具，店方聲稱他沒有民事權利，不能提出合同上的要求。分析的起點應是同等民事權利原則，再查有沒有相關特別規定。", "counter": "這條不能用來推論投票、居留或任何公共福利資格一律相同。", "advanced": "民事權利地位與涉外關係適用哪一法律，是不同問題。享有同等民事權利，不代表所有跨境交易都必然適用澳門法律。", "prompt": "遇到「不是居民，所以沒有權利」的說法，你會怎樣拆解？", "rubric": ["辨認所指權利", "區分民事與其他範疇", "說明平等原則", "查找有無法定例外"], "related": [14, 15], "questions": [{"q": "第13條對非本地居民的民事權利採取甚麼原則？", "options": ["原則同等，法律另有規定除外", "完全沒有民事權利", "只享有商戶自行批准的權利"], "answer": 0, "why": "本條以同等民事權利為原則，並明文保留法定例外。"}, {"q": "民事權利同等是否代表所有跨境關係必然適用澳門法律？", "options": ["是", "否，適用法律須另按衝突規範分析", "只要人在澳門便是"], "answer": 1, "why": "權利地位與準據法選擇是不同層次。"}]}, {"id": 14, "title": "選定法律後，哪些規定才適用？", "topic": "總則入門", "minutes": 9, "concept": "定性", "intro": "衝突規則為某一問題指定法律後，仍須按規定的內容和功能，判斷哪些規定屬於該規則所涉及的制度範疇。", "points": ["先辨認待解決的法律問題。", "查明衝突規則涉及哪一制度範疇。", "按規定的內容與功能判斷，不能只看章節名稱。"], "example": "假設某衝突規則已為繼承問題指定甲地法律。不能因此把甲地法律中所有合同、婚姻等規定一併套入；要辨认哪些規定在內容與功能上處理該繼承問題。", "counter": "一項規定被編在某章，不代表僅憑章名就已完成第14條的判斷。", "advanced": "本例只說明定性的分析方法，沒有替任何真實跨境繼承指定準據法。處理真實案件仍須先找到適用的具體衝突規則。", "prompt": "甲地某規定的章名與實際功能不同，你會如何分析？", "rubric": ["列出待決問題", "辨認衝突規則範疇", "分析規定內容", "說明制度功能"], "related": [15, 16], "questions": [{"q": "第14條判斷規定是否屬於相關制度範疇，重點是？", "options": ["只看條號", "內容及在該法律中的功能", "只看章名"], "answer": 1, "why": "條文明確以內容與功能作為判斷依據。"}, {"q": "指定甲地法律處理一個問題，是否一併適用甲地全部規定？", "options": ["是，整套搬入", "否，仍要辨認相關制度範疇的規定", "由當事人任意挑選"], "answer": 1, "why": "賦予準據法地位不等於無限制適用整套法律。"}]}, {"id": 15, "title": "指向外地法律，先讀哪一部分？", "topic": "總則入門", "minutes": 9, "concept": "域內法與衝突規範", "intro": "第15條的一般原則：指向澳門以外法律時，如無相反規定，只適用其域內法，即實體法，不包括衝突規範。", "points": ["實體法處理具體權利義務。", "衝突規範處理適用哪一法律。", "一般不把外地衝突規範一併引入；仍須查例外。"], "example": "假設澳門的衝突規範指向甲地法律。第一步按第15條理解為甲地處理該問題的實體規則，再檢查第16、17條等是否影響這個起點。", "counter": "「域內法」在本章的定義不是「凡在境內適用的一切規則」。", "advanced": "第15條須與第16條反致及第17條不接納反致的情況合讀。不要把一般原則寫成永無例外的結論。", "prompt": "如何向初學者解釋實體法與衝突規範的分別？", "rubric": ["權利義務問題", "適用法律問題", "第15條起點", "反致及其限制"], "related": [16, 17], "questions": [{"q": "本章的「域內法」指甚麼？", "options": ["實體法，不包括衝突規範", "只包括衝突規範", "包括所有地方行政文件"], "answer": 0, "why": "第15條第二款明確界定域內法。"}, {"q": "第15條的一般原則是否排除所有例外？", "options": ["是", "否，條文保留相反規定", "只看哪地法律較新"], "answer": 1, "why": "第一款訂明「如無相反規定」，須繼續核對例外。"}]}, {"id": 16, "title": "法律指來指去，如何處理？", "topic": "總則入門", "minutes": 9, "concept": "反致", "intro": "反致涉及被指定法律的衝突法再指向其他法律。第16條分別處理指向另一法律及指回澳門域內法的情況。", "points": ["先畫出澳門指向哪一法律。", "再查該法律的衝突法指向何處。", "指向第三地時，要確認該法律認為自己是準據法；亦須查第17條。"], "example": "假設澳門衝突規範指向甲地，甲地衝突法再指向乙地，而乙地認為自己適用。依第16條第一款的條件，可適用乙地的實體法；仍須核對第17條是否排除反致。", "counter": "不能只看到甲地指向乙地，便省略乙地是否認為自己適用的條件。", "advanced": "第二款另處理被指定法律的衝突法引用澳門域內法的情況。這些都是教學假設，未包含真實案件的全部連結因素。", "prompt": "澳門→甲地→乙地，還需要核對甚麼才能作結論？", "rubric": ["甲地衝突規範內容", "乙地是否接受適用", "適用的是域內法", "第17條是否排除"], "related": [15, 17], "questions": [{"q": "澳門指向甲地，甲地再指向乙地。第16條第一款還要求甚麼？", "options": ["乙地法律認為本身是準據法", "乙地離澳門較近", "當事人較喜歡乙地"], "answer": 0, "why": "第一款要求另一法律認為本身是規範有關情況的準據法。"}, {"q": "被指定法律的衝突法引用澳門域內法，且無第17條排除情況時，依第16條第二款適用甚麼？", "options": ["任選一地法律", "澳門域內法", "必然仍適用甲地實體法"], "answer": 1, "why": "第二款明定此情況適用澳門域內法。"}]}, {"id": 17, "title": "甚麼情況不接納反致？", "topic": "總則入門", "minutes": 9, "concept": "反致的限制", "intro": "即使第16條原本容許反致，第17條仍可能排除它，保護特定有效性及容許範圍內的當事人選法。", "points": ["比較按第15條與按第16條得出的法律效果。", "核對是否令原有效或生效的行為失去有效性或效力，或正當身分變為不正當。", "容許選法且當事人已指定法律時，不適用第16條。"], "example": "假設按第15條適用甲地實體法，某法律行為有效；若經第16條反致便變為無效，第17條第一款便要求不適用第16條。", "counter": "不是「任何對當事人較不利的結果」都必然排除反致；要核對法定情況。", "advanced": "第二款須同時注意法律容許當事人指定適用法律，以及當事人確已指定；並非在任何民事問題寫一句選法條款就足夠。", "prompt": "合同寫明適用某地法律，分析反致前要查甚麼？", "rubric": ["是否容許選法", "有無有效指定", "第17條第二款效果", "不可混同管轄法院與準據法"], "related": [15, 16], "questions": [{"q": "按第15條原有效的法律行為，經第16條反致會變為無效，第17條如何處理？", "options": ["仍必須反致", "不適用第16條", "一律重訂合同"], "answer": 1, "why": "第17條第一款排除造成所列有效性或效力損害的反致。"}, {"q": "當事人自行寫明適用法律，是否任何情況都符合第二款？", "options": ["是", "否，先要屬容許當事人指定法律的情況", "只要寫英文就可以"], "answer": 1, "why": "第二款的前提包括法律容許當事人選法。"}]}, {"id": 18, "title": "一個法律體系，有多個法制怎樣選？", "topic": "總則入門", "minutes": 9, "concept": "多元法的法律體系", "intro": "被指定的法律體系如按地域或人的因素有多個法制，且尚未指定哪個適用，先按該體系的標準確定。", "points": ["先確認是否確有多個法制共存。", "未指定具體法制時，先找該體系的選擇標準。", "不能確定標準時，才適用與情況較密切聯繫的法制。"], "example": "假設某被指定體系有甲區與乙區兩套法制，衝突規範尚未指明哪套。先查該體系如何分配適用範圍；不能確定標準，才比較與事件的聯繫。", "counter": "不能未查該體系的標準，就直接選較方便或對自己有利的一套。", "advanced": "多元法可基於地域，也可基於人的因素。本例只說明選擇順序，並不斷言任何具體地區的現行制度。", "prompt": "你找到兩套可能適用的法制，會按甚麼順序處理？", "rubric": ["確認指定層次", "查體系內部標準", "記錄不能確定的原因", "比較與事件的密切聯繫"], "related": [14, 15], "questions": [{"q": "第18條首先要求按甚麼確定具體法制？", "options": ["該法律體系所使用的標準", "當事人最方便的選項", "一律選人口最多地區"], "answer": 0, "why": "第一款先指向被指定法律體系本身使用的標準。"}, {"q": "不能確定該等標準時，下一步是？", "options": ["任意抽籤", "適用與有關情況有較密切聯繫的法制", "停止處理所有問題"], "answer": 1, "why": "第二款以較密切聯繫作後備準則。"}]}]);
